head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "jldstf31208";
scwin.pathname = undefined;
scwin.qry = undefined;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name init
 * @description 화면 초기화 — 파라미터 수신·기본값·컴포넌트 초기 설정(onpageload 에서 순차 호출)
 * @returns {void}
 * @hidden N
 */
scwin.init = function () {
    const ISU_CD = $c.util.getCookie("ISU_CD");
    const COM_NM = $c.util.getCookie("COM_NM");
    $c.util.getComponent("dma_CalcXhrReq").set("ISU_CD", ISU_CD);
    $c.util.getComponent("dma_CalcXhrReq").set("COM_NM", COM_NM);
};

/**
 * @method
 * @name init_recvParam
 * @description 화면 전환 파라미터 수신 — $c.data.getParameter() 를 dma_pageContext 에 담는다
 * @returns {void}
 * @hidden N
 */
scwin.init_recvParam = function () { dma_pageContext.setJSON($c.data.getParameter() ?? {}); };

try { scwin.pathname =location.pathname; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31208' }); }

try { scwin.qry =location.search; } catch (_e) { $c.exception.handleError(_e, { notify: 'none', context: 'jldstf31208' }); }

/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {void}
 * @hidden N
 */
scwin.onpageload = function () {
    try {
        scwin.init_recvParam();
    } catch (e) {
        $c.exception.handleError(e, { context: 'jldstf31208.onpageload' });
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_68_onclick
 * @description img_68 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_68_onclick = function(e){
    try {
        IsurcdSearch2('ISU_CD','COM_NM',315,155)

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31208.img_68_onclick' }); }
};

/**
 * @method
 * @name img_68_onmouseover
 * @description img_68 onmouseover 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.img_68_onmouseover = function(e){
    try {
        const ev = e;
        const selfVar = (ev && (ev.element || ev.target || ev.srcElement)) || this;
        selfVar.style.cursor='hand';

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31208.img_68_onmouseover' }); }
};

/**
 * @method
 * @name rd_sellRestrict_onclick
 * @description rd_sellRestrict 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 */
scwin.rd_sellRestrict_onclick = function(e){
    try {
        $c.util.getComponent('cal_startDT').className = 'form_number_readonly'; $c.util.getComponent('cal_startDT').setValue('')

    } catch (_ex) { $c.exception.handleError(_ex, { context: 'jldstf31208.rd_sellRestrict_onclick' }); }
};

/**
 * @method
 * @name btn_Calc_onclick
 * @description btn_Calc 클릭 이벤트
 * @param {Object} e 이벤트 객체
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.btn_Calc_onclick = async function(e){
    try {
        await scwin.calc()

    } catch (_ex) { await $c.exception.handleError(_ex, { context: 'jldstf31208.btn_Calc_onclick' }); }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name tx_fn_Calc_xhr
 * @description Calc xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_fn_Calc_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Calc_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_fn_Calc_xhr", unresolved: "action:self_submit:tx_fn_Calc_xhr" };
};

/**
 * @method
 * @name tx_init_xhr
 * @description init xhr 서버 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.tx_init_xhr = async function () {
    // ⛔주소가 없다 — as-is 는 «자기 자신» 에게 제출했는데(`self_submit`) 화면 자신의 액션 URL 을
    //   하나로 못 정했다(후보 0 또는 여럿). 빈 주소로 내보내면 «조용히 엉뚱한 곳» 이다.
    // TODO Stage2: 전환 미완(공급사 드러냄 — 사유 알림 유지) "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_init_xhr"
    throw { bizMessage: "이 화면의 제출 주소를 아직 정하지 못했습니다(전환 미완) — tx_init_xhr", unresolved: "action:self_submit:tx_init_xhr" };
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name calcBeforeOneYear
 * @description calc Before One Year 처리
 * @param {*} vDT vDT
 * @returns {void}
 * @hidden N
 */
scwin.calcBeforeOneYear = function (vDT) {
    const Vyear = vDT.substr(0, 4);
    const Vmonth = vDT.substr(4, 2);
    const Vday = vDT.substr(6, 2);
    const result = (Vyear - 1) + Vmonth + Vday;
    return result;
};

/**
 * @method
 * @name calc
 * @description calc 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.calc = async function () {
    let ISU_CD = $c.util.getComponent('ipt_ISU_CD').getValue(); if (ISU_CD == null) { ISU_CD = ''; }
    $c.util.setCookie("ISU_CD", ISU_CD, 1);
    $c.util.setCookie("COM_NM", $c.util.getComponent('ipt_COM_NM').getValue(), 1);
    if (ISU_CD === "") {
        await $c.win.alert("[종목코드]을 선택하세요.");
        ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').setFocus ? $c.util.getComponent('ipt_ISU_CD').setFocus() : ($c.util.getComponent('ipt_ISU_CD') && $c.util.getComponent('ipt_ISU_CD').focus ? $c.util.getComponent('ipt_ISU_CD').focus() : console.warn('[sdd] focus 대상 미해결: ipt_ISU_CD')));
        return;
    }
    if (($c.util.getComponent('cal_endDT').getValue() == null ? '' : String($c.util.getComponent('cal_endDT').getValue())) === '' || $c.util.getComponent('cal_endDT').getValue()=== "청약일") {
        await $c.win.alert("[종료일]을 입력하세요.");
        $c.util.getComponent("cal_endDT").focus();
        return;
    }
    if (($c.util.getComponent('rd_sellRestrict').getValue() === 'PERIOD') && ($c.util.getComponent('cal_startDT').getValue() == null ? '' : String($c.util.getComponent('cal_startDT').getValue())) === '') {
        await $c.win.alert("[시작일]을 입력하세요.");
        $c.util.getComponent("cal_startDT").focus();
        return;
    }
    if ($c.util.getComponent('cal_startDT').getValue()> $c.util.getComponent('cal_endDT').getValue()) {
        await $c.win.alert("시작일이 종료일보다 큽니다. 시작일을 다시 설정하세요");
        $c.util.getComponent("cal_startDT").focus();
        return;
    }
    if (($c.util.getComponent('rd_sellRestrict').getValue() === 'YEAR')) {
        $c.util.getComponent("cal_startDT").setValue(scwin.calcBeforeOneYear($c.util.getComponent('cal_endDT').getValue()));
        $c.util.getComponent('cal_startDT').className = "form_input";
    }
    $c.util.getComponent("dma_CalcXhrReq").set("ISU_CD", ISU_CD);
    $c.util.getComponent('dma_CalcXhrReq').set('method', "calculateSmallPlotLimit");
    const result = await scwin.tx_fn_Calc_xhr();
    const xmlDoc = xmlDocLoad(result);
    const dom = xmlDoc.selectNodes("//DATASET//DATA");
    if (dom.length > 0) {
        $c.util.getComponent("ipt_nowTotalCount").setValue(scwin.isNull(dom.item(0).selectSingleNode('tot_cnt').text));
        $c.util.getComponent("ipt_nowTotalMoney").setValue(scwin.isNull(dom.item(0).selectSingleNode('sum_isu_totamt').text));
        $c.util.getComponent("ipt_limitTotalMoney").setValue(scwin.isNull(dom.item(0).selectSingleNode('rest_limit_amt').text));
    } else {
        $c.util.getComponent("ipt_nowTotalCount").setValue("0");
        $c.util.getComponent("ipt_nowTotalMoney").setValue("0");
        $c.util.getComponent("ipt_limitTotalMoney").setValue("0");
    }
    const contHTML = $c.util.getComponent('txt_cont');
    let vHtmlText = "";
    if ($c.util.getComponent('ipt_nowTotalCount').getValue()<= 0) {
        vHtmlText += "<span style='color:red; padding-left:180px;'>";
        vHtmlText += "	<b><발행내역></b>";
        vHtmlText += "</span>";
        vHtmlText += "<table class='table_board_default_3' >";
        vHtmlText += "	<tr>";
        vHtmlText += "		<td class='board_subject_3' align='center' style='padding-top:10px;, padding-bottom:10px; padding-right:15px;'>";
        vHtmlText += "			<table width='100%' cellsapcing='0' cellpadding='0' border='0'>";
        vHtmlText += "				<tr>";
        vHtmlText += "					<td align='left' width='500'>";
        vHtmlText += "						검색결과가 존재하지 않습니다.";
        vHtmlText += "					</td>";
        vHtmlText += "				</tr>";
        vHtmlText += "		</td>";
        vHtmlText += "	</tr>";
        vHtmlText += "</table>";
    } else {
        vHtmlText += "<span style='color:red; padding-left:180px;'>";
        vHtmlText += "	<b><발행내역></b>";
        vHtmlText += "</span>";
        vHtmlText += "<table class='table_board_default_3' >";
        vHtmlText += "	<tr>";
        vHtmlText += "		<td class='board_subject_3' align='center' style='padding-top:10px;, padding-bottom:10px; padding-right:15px;'>";
        vHtmlText += "			<table width='100%' cellsapcing='0' cellpadding='0' border='0'>";
        for (i = 0; i < dom.length; i++) {
            vHtmlText += "				<tr>";
            vHtmlText += "					<td align='left'>";
            vHtmlText += dom.item(i).selectSingleNode('cont').text;
            vHtmlText += " 						<a href='" + dom.item(i).selectSingleNode('viewer_url').text + "' target='_blank'>[공시조회]</a>";
            vHtmlText += "					</td>";
            vHtmlText += "				</tr>";
        }
        vHtmlText += "			</table>";
        vHtmlText += "		</td>";
        vHtmlText += "	</tr>";
        vHtmlText += "</table>";
    }
    contHTML.innerHTML = vHtmlText;
};

/**
 * @method
 * @name checkNum
 * @description check Num 처리
 * @returns {void}
 * @hidden N
 */
scwin.checkNum = function () {
    if (event.keyCode === 8 || event.keyCode === 46) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 48 && $c.util.getKeyCode(event) <= 57) {
        return true;
    }
    if ($c.util.getKeyCode(event) >= 96 && $c.util.getKeyCode(event) <= 105) {
        return true;
    }
    return false;
};

/**
 * @method
 * @name makeCategory
 * @description make Category 처리
 * @param {*} xml xml
 * @returns {void}
 * @hidden N
 */
scwin.makeCategory = function (xml) {
    const xmlDoc = xmlDocLoad(xml);
    const dom = xmlDoc.selectNodes("//DATASET//DATA");
    const obj = (document.frm || { elements: [] }).sameCategory;
    const objLength = obj.length;
    for (i = 0; i < dom.length; i++) {
        const text = dom.item(i).selectSingleNode('idx_ind_nm').text;
        const value = dom.item(i).selectSingleNode('idx_ind_cd').text;
        obj[i+1] = new Option(text, value);
    }
};

/**
 * @method
 * @name isNull
 * @description is Null 처리
 * @param {*} value value
 * @returns {void}
 * @hidden N
 */
scwin.isNull = function (value) {
    if (value === 'null' || value === '') {
        value = '0';
    }
    return value;
};
